using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectClips{public static string Run(){return string.Join("\n",AssetDatabase.FindAssets("t:AnimationClip",new[]{"Assets/07_Animacion/DoubleL/FBX Unity","Assets/Kevin Iglesias/Human Animations/Animations/Male/Movement"}).Select(AssetDatabase.GUIDToAssetPath).Distinct().Where(p=>!p.EndsWith(".meta")&&(p.Contains("Attack")||p.Contains("Jump")||p.Contains("Run01")||p.Contains("Idle_A"))).SelectMany(p=>AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__")).Select(c=>p+" length="+c.length+" human="+c.isHumanMotion)));}}
